// Photo safety: only real JPEG / PNG / WebP bytes are accepted and served.
// The client-declared MIME type / extension is never trusted.

export const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp"];

// Small raster placeholder for admin TEST cards (replaces the old inline SVG).
export const TEST_CARD_PNG_DATA_URL = "data:image/png;base64,";

export function sniffImageType(bytes) {
  if (!bytes || bytes.length < 12) return null;
  const b = bytes;
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return "image/jpeg";
  if (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47 &&
      b[4] === 0x0d && b[5] === 0x0a && b[6] === 0x1a && b[7] === 0x0a) return "image/png";
  if (b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 &&
      b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50) return "image/webp";
  return null;
}

export function decodeBase64Bytes(b64) {
  const clean = String(b64 || "").replace(/\s+/g, "");
  if (!clean || !/^[A-Za-z0-9+/]+={0,2}$/.test(clean)) return null;
  try {
    const bin = atob(clean);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  } catch (e) {
    return null;
  }
}

// Parse any stored/uploaded data URL. Returns { mime, bin } with mime derived from the bytes
// (null if the bytes are not an allowed image), or null if it is not a decodable base64 data URL.
export function parseImageDataUrl(data) {
  const s = String(data || "");
  if (!s.startsWith("data:")) return null;
  const comma = s.indexOf(",");
  if (comma < 0) return null;
  const meta = s.slice(0, comma);
  if (!/;base64$/i.test(meta)) return null;
  const bin = decodeBase64Bytes(s.slice(comma + 1));
  if (!bin) return null;
  return { mime: sniffImageType(bin), bin };
}

// Upload validation: returns a canonical data URL "data:<sniffed>;base64,..." or null.
// Only the first bytes are decoded (cheap on CPU); the whole payload must be valid base64.
export function sanitizeImageDataUrl(data) {
  const s = String(data || "");
  if (!s.startsWith("data:")) return null;
  const comma = s.indexOf(",");
  if (comma < 0 || !/;base64$/i.test(s.slice(0, comma))) return null;
  const b64 = s.slice(comma + 1).replace(/\s+/g, "");
  if (b64.length < 16 || b64.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(b64)) return null;
  const head = decodeBase64Bytes(b64.slice(0, 24));
  const mime = sniffImageType(head);
  if (!mime) return null;
  return "data:" + mime + ";base64," + b64;
}

// Response for a stored photo: type from magic bytes + hardening headers.
// Anything that is not JPEG/PNG/WebP is served as an inert download.
export function safeImageResponse(bin, extraHeaders) {
  const mime = sniffImageType(bin);
  const headers = {
    ...(extraHeaders || {}),
    "x-content-type-options": "nosniff",
    "content-security-policy": "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox",
    "referrer-policy": "no-referrer"
  };
  if (mime) {
    headers["content-type"] = mime;
  } else {
    headers["content-type"] = "application/octet-stream";
    headers["content-disposition"] = "attachment; filename=\"file.bin\"";
    delete headers["access-control-allow-origin"];
  }
  return new Response(bin, { headers });
}
